import{c as t,Q as i,j as o,m as a}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"Changelog","description":"Version history for GateKeeper.","frontmatter":{"title":"Changelog","description":"Version history for GateKeeper."},"headers":[],"relativePath":"src/content/docs/reference/changelog.md","filePath":"src/content/docs/reference/changelog.md"}'),n={name:"src/content/docs/reference/changelog.md"};function s(r,e,l,d,c,g){return i(),o("div",null,[...e[0]||(e[0]=[a('<h2 id="v0-4-0" tabindex="-1">v0.4.0 <a class="header-anchor" href="#v0-4-0" aria-label="Permalink to &quot;v0.4.0&quot;">​</a></h2><h3 id="security-hardening" tabindex="-1">Security hardening <a class="header-anchor" href="#security-hardening" aria-label="Permalink to &quot;Security hardening&quot;">​</a></h3><ul><li><strong>AES-256-GCM for TOTP secrets</strong> - TOTP secrets are now encrypted with AES-256-GCM before storage. The encryption key is derived from <code>SECRET_KEY</code> using SHA-256. Existing secrets encrypted with the older XOR scheme are migrated automatically on next login - no action required.</li><li><strong>HMAC-SHA256 for OTP codes</strong> - Email OTP codes are no longer stored as plaintext. They are stored as HMAC-SHA256 digests keyed with <code>SECRET_KEY</code>. A database dump without the key cannot reconstruct active codes.</li><li><strong>CSRF protection on all user endpoints</strong> - All authenticated state-changing POST requests (password change, 2FA enrollment, session revocation, passkey deletion, name and avatar update) now validate a CSRF token. Previously only the admin panel validated CSRF.</li><li><strong>Login rate limiting</strong> - The login endpoint now enforces an IP-based rate limit of 20 failed attempts per 15-minute window. Excess attempts receive an error before any password check.</li><li><strong>OTP issuance rate limit</strong> - Each user can request at most 3 OTP codes per 10-minute window, preventing email flooding.</li><li><strong>Tightened Content-Security-Policy</strong> - Added <code>object-src &#39;none&#39;</code>, <code>base-uri &#39;self&#39;</code>, <code>connect-src &#39;self&#39;</code>, and <code>frame-ancestors &#39;none&#39;</code>. Added <code>https://www.gravatar.com</code> to <code>img-src</code>.</li></ul><h3 id="user-home-redesign" tabindex="-1">User home redesign <a class="header-anchor" href="#user-home-redesign" aria-label="Permalink to &quot;User home redesign&quot;">​</a></h3><ul><li><strong>New user home layout</strong> - The authenticated home page (<code>/</code>) is fully redesigned. It shows a header with the GateKeeper logo, email, and theme toggle; a page head with avatar, display name, and inline name edit; three stat cards (sign-in methods, passkeys, sessions); a sign-in methods card; a passkeys card; and an active sessions card.</li><li><strong>Session management</strong> - Users can view all active sessions (device, browser, IP, last seen, time ago) and revoke individual sessions or all sessions except the current one directly from the home page.</li></ul><h2 id="v0-3-0" tabindex="-1">v0.3.0 <a class="header-anchor" href="#v0-3-0" aria-label="Permalink to &quot;v0.3.0&quot;">​</a></h2><ul><li><strong>Webhooks</strong> - Send push notifications to Discord, Slack, Telegram, ntfy (public and self-hosted), generic JSON endpoints, or email when auth and admin events occur. Configure per-webhook event subscriptions and test delivery inline from the Webhooks page.</li><li><strong>Access policies</strong> - Create named policies and assign users to them. Attach a policy to an OIDC client to restrict which users can complete authorization, or reference it via <code>?policy=&lt;name&gt;</code> on <code>/auth/verify</code> for ForwardAuth routes. Policy ForwardAuth URL shown with copy button on the policies page.</li><li><strong>Admin audit logging</strong> - Admin sign-in (password and passkey), sign-out, failed login attempts, and user deletion are now recorded in the audit log alongside all other events.</li><li><strong>Audit log retention</strong> - Set a retention period in Settings. Events older than the configured number of days are deleted automatically on startup and daily. Default is 90 days; set to 0 to keep all events.</li><li><strong>Audit log date filter</strong> - Filter by Today, 7 days, 30 days, 90 days, or All time directly from the toolbar.</li><li><strong>User profile</strong> - Users can set a display name and pull in a Gravatar avatar from their home screen. The image is fetched server-side and cached in the database so the browser never contacts Gravatar directly.</li><li><strong>Avatars everywhere</strong> - Display name and avatar appear in the admin user list, user detail page, audit log rows, and dashboard recent events.</li><li><strong>Dashboard redesign</strong> - Real sparklines from the database on the sign-ins, failed attempts, and OIDC traffic cards. New cards for active sessions, 2FA adoption, and audit log stats. Auth methods card with 24h / 7d / 30d range toggle.</li><li><strong>Command palette fixes</strong> - <code>⌘K</code> / <code>Ctrl+K</code> palette now has working keyboard navigation (arrow keys, Enter). All pages including Policies, Webhooks, and Integrations appear in the navigate list. Searching users matches display name in addition to email.</li><li><strong>New user modal</strong> - Creating a user from the Users page now opens an inline modal instead of navigating to a separate page.</li><li><strong>Policies table</strong> - Policies page redesigned to match the OIDC clients table layout with description, member count, and used-by columns.</li><li><strong>System health section</strong> - Consolidates configuration warnings (locked accounts, users without 2FA, OIDC signing key status).</li></ul><h2 id="v0-2-0" tabindex="-1">v0.2.0 <a class="header-anchor" href="#v0-2-0" aria-label="Permalink to &quot;v0.2.0&quot;">​</a></h2><ul><li><strong>OIDC provider</strong> - Full authorization code + PKCE flow. Apps can now use GateKeeper as a proper OIDC identity provider (Traefik Manager, Termix, Grafana, Jellyfin, etc.)</li><li><strong>OIDC client icons</strong> - Add an icon URL per client. Icons are fetched and cached server-side at save time; the login page loads them from GateKeeper, not external servers.</li><li><strong>Login page branding</strong> - When signing in via OIDC, the login page shows the app name and cached icon instead of the GateKeeper logo.</li><li><strong>Client editing</strong> - Edit name, icon, redirect URIs, and optionally rotate the secret of any OIDC client without deleting and recreating it.</li><li><strong>OIDC endpoint reference</strong> - The clients page now shows all endpoint URLs (authorization, token, userinfo, JWKS, discovery) with copy buttons.</li><li><strong>Secret generator</strong> - One-click cryptographically random secret generation in the new/edit client dialogs.</li><li><strong>Trusted device tokens</strong> - After passing 2FA, a 30-day <code>gk_trust</code> cookie is set. Users on trusted devices skip the second factor until it expires.</li><li><strong>Cross-domain ForwardAuth</strong> - HMAC-signed short-lived tokens allow GateKeeper to set per-host cookies for apps on different TLDs.</li><li><strong>Interactive dashboard chart</strong> - Sign-in activity chart with 24h / 7d / 30d range toggle and hover tooltips backed by real data.</li><li><strong>Real auth method breakdown</strong> - Dashboard shows live percentages for passkey, TOTP, email OTP, and OIDC logins in the last 24 hours.</li><li><strong>Command palette</strong> - <code>⌘K</code> / <code>Ctrl+K</code> opens a search palette. Type to search users and clients by name. Keyboard shortcuts <code>g d/u/c/a/s</code> navigate between sections.</li><li><strong>Audit log improvements</strong> - Event type filter chips (auth / admin / oidc), kind filter (success / warn / fail / info), per-row filter button, correct event count.</li><li><strong>Mobile navigation</strong> - Bottom navigation bar on screens under 760px.</li><li><strong>Admin sidebar</strong> - Live user and client counts, version number in the footer.</li><li><strong>New user sign-in methods</strong> - Create users as &quot;Email + Password&quot; or &quot;Email Only&quot; (passwordless) directly from the new user form.</li><li><strong>OIDC post-login redirect</strong> - After authenticating via OIDC, GateKeeper correctly completes the auth request and redirects back to the app with an authorization code.</li><li><strong>Theme persistence</strong> - Dark/light/auto preference now survives full page navigation (was blocked by CSP preventing the inline bootstrap script).</li></ul><h2 id="v0-1-0" tabindex="-1">v0.1.0 <a class="header-anchor" href="#v0-1-0" aria-label="Permalink to &quot;v0.1.0&quot;">​</a></h2><p>Initial release.</p><ul><li>Password + email OTP login</li><li>Passwordless email OTP mode (per-user, admin-configurable)</li><li>TOTP enrollment with QR code and recovery codes</li><li>Passkey (WebAuthn) registration and authentication</li><li>Password recovery via email with rate-limited, single-use tokens</li><li>Authenticated password change with session invalidation</li><li>Forced password change on admin-created accounts</li><li>Traefik ForwardAuth middleware (<code>/auth/verify</code>)</li><li>OIDC provider with authorization code + PKCE flow</li><li>OIDC scopes: <code>openid</code>, <code>email</code>, <code>profile</code>, <code>offline_access</code></li><li>RS256 signing with 30-day key rotation</li><li>First-run setup page at <code>/admin/setup</code> - no env vars needed for admin credentials</li><li>Admin UI for user and OIDC client management</li><li>Admin profile page - change password, enroll TOTP, register passkeys</li><li>All runtime settings (SMTP, session TTL, allowed domains) configurable in the admin UI</li><li>Append-only audit log</li><li>SQLite persistence with embedded migrations</li><li>Docker multi-stage build (golang:1.26-alpine)</li><li>Astro Starlight documentation site</li></ul>',12)])])}const p=t(n,[["render",s]]);export{u as __pageData,p as default};
